  const grade: Celula[][] = []
  for (let linha = 0; linha < linhas; linha++) {
    const fileira: Celula[] = []
    for (let coluna = 0; coluna < colunas; coluna++) fileira.push(null)
    grade.push(fileira)
  }
  return { linhas, colunas, grade, moedas }
}

export function reabrir(jardim: Jardim): Jardim {
  return carregar(salvar(jardim))
}

export function podeConstruir(
  jardim: Jardim,
  linha: number,
  coluna: number,
  tipo: Planta,
): boolean {
  return true
}
export function construir(
  jardim: Jardim,
  linha: number,
  coluna: number,
  tipo: Planta,
): Jardim {
  return jardim
}
export function colher(jardim: Jardim): Jardim {
  return jardim
}
export function salvar(jardim: Jardim): string {
  return ''
}

export function carregar(texto: string): Jardim {
  return novoJardim(1, 1, 0)
}
